18	// GPU runs ACE-Step's three transformer stacks on the device: the lyric
19	// encoder (8 layers), the timbre encoder (4) and the DiT (32), over the
20	// image DiT's validated kernels (the fragment-tiled fp16 GEMM, the WMMA
21	// flash attention, the packs, SwiGLU, the gated residual) and H3's modulated
22	// norm and q/k pack, plus this vertical's three attention builds
23	// (shaders/ace_*: GQA with the tail out of the row max, the ±128 band, and
24	// cross-attention).
25	//
26	// What is different from h3/dit, and why:
27	//
28	//   - **No row chunks and no runs.** A 10-minute song is 7,500 tokens, and
29	//     every row of one forward shares one timestep, so a stage is one
30	//     dispatch over the whole sequence and the AdaLN vectors are one set a
31	//     layer a forward.
32	//   - **GQA everywhere**: 32 query heads over 8 kv heads in the DiT, 16 over
33	//     8 in the encoders; k and v are projected and packed at kv width.
34	//   - **Cross-attention with K/V computed once a request** (Begin). Every
35	//     layer's condition keys and values are packed into their own planes,
36	//     ~10 MB a layer, and the step reads them 8 times.
37	//   - **fp32 residual, fp16 operands, no FFN scale** (A-o1: the residual
38	//     reaches 5.7e5, every GEMM operand stays under 2.45e3).
39	//   - **The encoders are this block without modulation**: a = the norm
40	//     weight, b = 0, and a plain residual add.
41	type GPU struct {
42		// Between, when set, is called between two submissions, when nothing of
43		// this model's is on the device (h3/dit's hook, for a server).
44		Between func() error
45	
46		dev *vk.Device
47		cfg *Config
48		// big is the kernel every big projection runs on: gemmBig, or what a
49		// screen sets (TestGPUStepTiming's ACE_DIT_BIG).
50		big  gemmKernel
51		Host *Host
52	
53		wbuf, abuf, hbuf *vk.Buffer
54		banks            []*vk.Buffer
55		pipes            map[string]*vk.ComputePipeline
56		gemms            []map[gemmKernel]*vk.ComputePipeline
57		mods             []*vk.ShaderModule
58	
59		dit, enc  dims
60		maxTokens int
61		rows      int // plane and scratch rows: every sequence here fits in it
62		encRows   int // the cross planes' rows
63		maxEnc    int // longest condition sequence
64	
65		ditL, lyricL, timbreL []layerW
66		detokL, poolL         []layerW
67		projIn, projOut       headW
68		condEmb, textProj     headW
69		lyricIn, timbreIn     headW
70		detokIn, detokOut     headW
71		tokIn                 headW // the tokenizer's two input projections, folded
72	
73		// wbuf (fp32): rope tables, identity tables, the detokenizer's tables
74		// (position = row mod 5) and the tokenizer's pooler's (row mod 6), q/k
75		// norm weights.
76		wCos, wSin, wCosID, wSinID uint32
77		wCosG, wSinG               uint32
78		wCosP, wSinP               uint32
79		// abuf (fp32): residual, scratch, per-step modulation, encoder norms.
80		aX, aS, aMod, aTail, aZeros, aOnes uint32
81		aProjInB, aLyricB, aTimbreB        uint32
82		aDetokNorm, aPoolNorm              uint32
83		actElems                           int
84		// hbuf (fp16): planes, A operands, the cross planes.
85		hQ, hK, hV, hA, hCtx, hFFN, hIn uint32
86		hElems                          int
87	
88		// Per-request state (Begin).
89		encLen int
90	
91		// detokChunk, when set, is how many codes Detokenize runs at a time:
92		// the test's way to exercise the chunking at a short song.
93		detokChunk int
94	}
