96	type dims struct {
97		H, heads, kv, ffn  int
98		ldaH, ldaQ, ldaFFN int
99	}
100	
101	func (d dims) qW() int  { return d.heads * headDim }
102	func (d dims) kvW() int { return d.kv * headDim }
