110	type proj int
111	
112	const (
113		pQ proj = iota
114		pK
115		pV
116		pO
117		pGate
118		pUp
119		pDown
120		pCQ // cross-attention: q from the residual, k/v from the condition
121		pCK
122		pCV
123		pCO
124	)
