126	type layerW struct {
127		bank   int
128		off    map[proj]uint32
129		window bool
130		// group > 0 makes self-attention block-diagonal over groups of that
131		// many rows, with rope positions restarting every group (the
132		// detokenizer's 5-row sequences).
133		group int
134		// wbuf: q/k norm weights; cross-attention's own pair on the DiT.
135		normQ, normK, cnormQ, cnormK uint32
136		// abuf: the encoders' input/post-attention norms, the DiT's cross norm.
137		norm1, norm2, crossNorm uint32
138		// hbuf: the DiT layer's cross-attention key and value planes.
139		crossK, crossV uint32
140	}
