142	// pushConstants mirrors shaders/dit_common.glsl.
143	type pushConstants struct {
144		InOff, OutOff, WOff uint32
145		Tokens, Dim, Heads  uint32
146		HeadDim, Span       uint32
147		KOff, VOff, KStride uint32
148		Eps, Scale          uint32
