161	type gemmKernel int
162	
163	const (
164		gemmBig    gemmKernel = iota // 128x256 tiles
165		gemmSmall                    // 64x64, for the 128-wide output head
166		gemmBigW64                   // the wave64 128x256 build, for short clips (bigW64Rows)
167	)
168	
169	// bigW64Rows is the row count up to which the big projections run on the
170	// wave64 build (KERNELS.md G8, 2026-09-29): at 375 rows (a 30 s clip) the
171	// LDS-staged build is 8% slower a forward (130 against 120 ms; its grid is
172	// 30 workgroups and the per-slab barrier shows), the two tie at 1500, and
173	// from 3000 rows the LDS build wins by 2.5-3%. The 64x64 rung is never the
174	// answer (131 ms at 375, 1.2-1.4x slower above).
175	const bigW64Rows = 1024
176	
177	var gemmVariants = map[gemmKernel]struct {
178		spirv  []byte
179		bm, bn int
180		bk     int    // the K tile: 32 for the LDS-staged build, 16 otherwise
181		wave   uint32 // a pinned subgroup size, or 0 for the device's default
182	}{
183		// The LDS-staged wave32 build (KERNELS.md G2, research §2.9), bit-identical
184		// to the wave64 one it replaced.
185		gemmBig:   {shaders.DiTGEMMWG128x256LDSW32, 128, 256, 32, 32},
186		gemmSmall: {shaders.DiTGEMMReg64Tiled, 64, 64, 16, 0},
187		// The wave64 build gemmBig replaced, which still wins up to bigW64Rows.
188		gemmBigW64: {shaders.DiTGEMMWG128x256TiledSWZ8, 128, 256, 16, 0},
189	}
190	
191	const (
192		tile     = 16
193		headDim  = 128
194		gemmPad  = 128
195		rowAlign = 128
196		log2e    = 1.4426950408889634
197		// maxKeyBlock is the key block every attention build reads whole.
198		maxKeyBlock = 4 * tile
199		// MaxLyricTokens and MaxTextTokens are upstream's truncations.
200		MaxLyricTokens = 2048
201		MaxTextTokens  = 256
202		// TimbreRows is the silence reference's 750 frames plus the CLS row.
203		TimbreRows   = 751
204		maxBankBytes = 0xfffffffc
205	)
206	
207	func roundUp(n, m int) int { return (n + m - 1) / m * m }
208	
209	// NewGPU stages the encoders and the DiT for songs of up to maxTokens DiT
210	// tokens (12.5 a second; 7,500 is upstream's 10-minute ceiling).
211	func NewGPU(dev *vk.Device, dir string, maxTokens int) (*GPU, error) {
212		cfg, err := LoadConfig(dir)
213		if err != nil {
214			return nil, err
215		}
216		set, err := safetensors.OpenSet(dir)
217		if err != nil {
218			return nil, err
219		}
220		defer set.Close()
221		host, err := LoadHost(set, cfg)
222		if err != nil {
223			return nil, err
224		}
225		g := &GPU{dev: dev, cfg: cfg, Host: host, maxTokens: maxTokens, pipes: map[string]*vk.ComputePipeline{}, big: gemmBig}
226		g.dit = dims{H: cfg.Hidden, heads: cfg.Heads, kv: cfg.KVHeads, ffn: cfg.FFN}
227		g.enc = dims{H: cfg.EncHidden, heads: cfg.EncHeads, kv: cfg.EncKVHeads, ffn: cfg.EncFFN}
228		for _, d := range []*dims{&g.dit, &g.enc} {
229			d.ldaH, d.ldaQ, d.ldaFFN = d.H+gemmPad, d.qW()+gemmPad, d.ffn+gemmPad
230		}
231		g.maxEnc = MaxLyricTokens + 1 + MaxTextTokens
232		g.encRows = roundUp(g.maxEnc, rowAlign)
233		g.rows = roundUp(max(maxTokens, g.maxEnc, TimbreRows), rowAlign)
234		for _, step := range []func(*safetensors.Set) error{g.stage, g.allocActivations, g.build} {
235			if err := step(set); err != nil {
236				g.Destroy()
237				return nil, err
238			}
239		}
240		return g, nil
241	}
242	
243	func parallel(n int, fn func(i int)) {
244		w := min(runtime.GOMAXPROCS(0), n)
245		var wg sync.WaitGroup
246		next := make(chan int, n)
247		for i := 0; i < n; i++ {
248			next <- i
249		}
250		close(next)
251		wg.Add(w)
252		for ; w > 0; w-- {
253			go func() {
254				defer wg.Done()
255				for i := range next {
256					fn(i)
257				}
258			}()
259		}
260		wg.Wait()
261	}
262	
263	// packB narrows a [n, k] row-major weight into 16x16 fragment tiles,
264	// kt-fastest: dit_gemm.comp's B layout.
265	func packB(dst []uint16, w []float32, n, k int) {
266		kt := k / tile
267		parallel((n+63)/64, func(c int) {
268			for i := c * 64; i < min((c+1)*64, n); i++ {
269				row := w[i*k : (i+1)*k]
270				base := (i / tile) * kt * tile * tile
271				lane := (i % tile) * tile
272				for j, v := range row {
273					dst[base+(j/tile)*tile*tile+lane+j%tile] = safetensors.F32ToF16(v)
274				}
275			}
276		})
277	}
278	
279	func (g *GPU) projShape(d dims, p proj) [2]int {
280		switch p {
281		case pQ, pCQ:
282			return [2]int{d.qW(), d.H}
283		case pK, pV, pCK, pCV:
284			return [2]int{d.kvW(), d.H}
285		case pO, pCO:
286			return [2]int{d.H, d.qW()}
287		case pGate, pUp:
288			return [2]int{d.ffn, d.H}
289		default:
290			return [2]int{d.H, d.ffn}
291		}
292	}
293	
294	var (
295		selfProjs  = []proj{pQ, pK, pV, pO, pGate, pUp, pDown}
296		crossProjs = []proj{pCQ, pCK, pCV, pCO}
297		projNames  = map[proj]string{
298			pQ: "self_attn.q_proj", pK: "self_attn.k_proj", pV: "self_attn.v_proj", pO: "self_attn.o_proj",
299			pGate: "mlp.gate_proj", pUp: "mlp.up_proj", pDown: "mlp.down_proj",
300			pCQ: "cross_attn.q_proj", pCK: "cross_attn.k_proj", pCV: "cross_attn.v_proj", pCO: "cross_attn.o_proj",
301		}
302	)
303	
304	// stage lays out and fills the fp16 banks and the fp32 weight arena.
305	func (g *GPU) stage(set *safetensors.Set) error {
306		c := g.cfg
307		var bankElems []int
308		cur := -1
309		place := func(n int) (int, uint32) {
310			if cur < 0 || (bankElems[cur]+n)*2 > maxBankBytes {
311				bankElems = append(bankElems, 0)
312				cur = len(bankElems) - 1
313			}
314			off := bankElems[cur]
315			bankElems[cur] += n
316			return cur, uint32(off)
317		}
318		head := func(n, k int) headW {
319			b, off := place(n * k)
320			return headW{bank: b, off: off, n: n, k: k}
321		}
322		g.projIn = head(g.dit.H, c.PatchIn())
323		g.projOut = head(c.PatchOut(), g.dit.H)
324		g.condEmb = head(g.dit.H, g.enc.H)
325		g.textProj = head(g.enc.H, c.TextDim)
326		g.lyricIn = head(g.enc.H, c.TextDim)
327		g.timbreIn = head(g.enc.H, c.TimbreDim)
328		g.detokIn = head(g.enc.H, g.enc.H)
329		g.detokOut = head(c.Latent, g.enc.H)
330		g.tokIn = head(g.enc.H, c.Latent)
331	
332		ropeHalf := headDim / 2
333		g.wCos, g.wSin = 0, uint32(g.rows*ropeHalf)
334		g.wCosID, g.wSinID = uint32(2*g.rows*ropeHalf), uint32(3*g.rows*ropeHalf)
335		g.wCosG, g.wSinG = uint32(4*g.rows*ropeHalf), uint32(5*g.rows*ropeHalf)
336		g.wCosP, g.wSinP = uint32(6*g.rows*ropeHalf), uint32(7*g.rows*ropeHalf)
337		w32 := 8 * g.rows * ropeHalf
338		newLayer := func(d dims, i int, cross bool) layerW {
339			w := layerW{off: map[proj]uint32{}, window: c.Windowed(i)}
340			ps := selfProjs
341			if cross {
342				ps = append(append([]proj(nil), selfProjs...), crossProjs...)
343			}
344			n := 0
345			for _, p := range ps {
346				sh := g.projShape(d, p)
347				n += sh[0] * sh[1]
348			}
349			b, off := place(n)
350			w.bank = b
351			for _, p := range ps {
352				sh := g.projShape(d, p)
353				w.off[p] = off
354				off += uint32(sh[0] * sh[1])
355			}
356			w.normQ, w.normK = uint32(w32), uint32(w32+headDim)
357			w32 += 2 * headDim
358			if cross {
359				w.cnormQ, w.cnormK = uint32(w32), uint32(w32+headDim)
360				w32 += 2 * headDim
361			}
362			return w
363		}
364		for i := 0; i < c.LyricLayers; i++ {
365			g.lyricL = append(g.lyricL, newLayer(g.enc, i, false))
366		}
367		for i := 0; i < c.TimbreLayers; i++ {
368			g.timbreL = append(g.timbreL, newLayer(g.enc, i, false))
369		}
370		for i := 0; i < c.Layers; i++ {
371			g.ditL = append(g.ditL, newLayer(g.dit, i, true))
372		}
373		for i := 0; i < c.DetokLayers; i++ {
374			w := newLayer(g.enc, i, false)
375			w.window, w.group = false, c.PoolWindow
376			g.detokL = append(g.detokL, w)
377		}
378		for i := 0; i < c.DetokLayers; i++ {
379			w := newLayer(g.enc, i, false)
380			w.window, w.group = false, c.PoolWindow+1
381			g.poolL = append(g.poolL, w)
382		}
383	
384		var err error
385		if g.wbuf, err = g.dev.NewBuffer(w32 * 4); err != nil {
386			return fmt.Errorf("dit: fp32 weight arena: %w", err)
387		}
388		for _, n := range bankElems {
389			b, err := g.dev.NewBuffer(n * 2)
390			if err != nil {
391				return fmt.Errorf("dit: fp16 bank %d (%d MB): %w", len(g.banks), (n*2)>>20, err)
392			}
393			g.banks = append(g.banks, b)
394		}
395	
396		// Rotary tables: Qwen3's inv_freq and angles, formed in fp32 as torch
397		// forms them; and the identity pair cross-attention's q/k pack reads.
398		cos, sin := make([]float32, g.rows*ropeHalf), make([]float32, g.rows*ropeHalf)
399		ones := make([]float32, g.rows*ropeHalf)
400		for j := 0; j < ropeHalf; j++ {
401			e := float32(2*j) / float32(headDim)
402			inv := 1 / float32(math.Pow(c.Theta, float64(e)))
403			for p := 0; p < g.rows; p++ {
404				a := float32(p) * inv
405				cos[p*ropeHalf+j] = float32(math.Cos(float64(a)))
406				sin[p*ropeHalf+j] = float32(math.Sin(float64(a)))
407				ones[p*ropeHalf+j] = 1
408			}
409		}
410		g.wbuf.WriteFloat32At(int(g.wCos), cos)
411		g.wbuf.WriteFloat32At(int(g.wSin), sin)
412		g.wbuf.WriteFloat32At(int(g.wCosID), ones)
413		g.wbuf.ZeroFloat32At(int(g.wSinID), g.rows*ropeHalf)
414		// Position row mod the group: every detokenizer group (5 rows) and
415		// every pooler group (a CLS row and 5) starts at 0.
416		for _, gt := range []struct {
417			n        int
418			cos, sin uint32
419		}{{c.PoolWindow, g.wCosG, g.wSinG}, {c.PoolWindow + 1, g.wCosP, g.wSinP}} {
420			cosG, sinG := make([]float32, g.rows*ropeHalf), make([]float32, g.rows*ropeHalf)
421			for r := 0; r < g.rows; r++ {
422				p := r % gt.n
423				copy(cosG[r*ropeHalf:(r+1)*ropeHalf], cos[p*ropeHalf:(p+1)*ropeHalf])
424				copy(sinG[r*ropeHalf:(r+1)*ropeHalf], sin[p*ropeHalf:(p+1)*ropeHalf])
425			}
426			g.wbuf.WriteFloat32At(int(gt.cos), cosG)
427			g.wbuf.WriteFloat32At(int(gt.sin), sinG)
428		}
429	
430		put := func(bank int, off uint32, w []float32, n, k int) {
431			buf := make([]uint16, n*k)
432			packB(buf, w, n, k)
433			g.banks[bank].WriteUint16At(int(off), buf)
434		}
435		l := &loader{set: set}
436		// proj_in is a Conv1d(192 → 2560, k2, s2): W[o, c, k] becomes
437		// W'[o, k·192 + c], so a token's operand row is its two frames of
438		// [context | x_t] side by side.
439		{
440			in, p := c.InChannels, c.Patch
441			w := l.f32("decoder.proj_in.1.weight", g.dit.H, in, p)
442			if l.err != nil {
443				return l.err
444			}
445			r := make([]float32, len(w))
446			for o := 0; o < g.dit.H; o++ {
447				for ch := 0; ch < in; ch++ {
448					for k := 0; k < p; k++ {
449						r[o*p*in+k*in+ch] = w[(o*in+ch)*p+k]
450					}
451				}
452			}
453			put(g.projIn.bank, g.projIn.off, r, g.projIn.n, g.projIn.k)
454		}
455		// proj_out is a ConvTranspose1d(2560 → 64, k2, s2): W[c, o, k] becomes
456		// W'[k·64 + o, c], so output column k·64 + o is frame 2i + k's channel o.
457		{
458			lat, p := c.Latent, c.Patch
459			w := l.f32("decoder.proj_out.1.weight", g.dit.H, lat, p)
460			if l.err != nil {
461				return l.err
462			}
463			r := make([]float32, len(w))
464			for ch := 0; ch < g.dit.H; ch++ {
465				for o := 0; o < lat; o++ {
466					for k := 0; k < p; k++ {
467						r[(k*lat+o)*g.dit.H+ch] = w[(ch*lat+o)*p+k]
468					}
469				}
470			}
471			put(g.projOut.bank, g.projOut.off, r, g.projOut.n, g.projOut.k)
472		}
473		for _, hd := range []struct {
474			w    headW
475			name string
476		}{
477			{g.condEmb, "decoder.condition_embedder.weight"},
478			{g.textProj, "encoder.text_projector.weight"},
479			{g.lyricIn, "encoder.lyric_encoder.embed_tokens.weight"},
480			{g.timbreIn, "encoder.timbre_encoder.embed_tokens.weight"},
481			{g.detokIn, "detokenizer.embed_tokens.weight"},
482			{g.detokOut, "detokenizer.proj_out.weight"},
483		} {
484			w := l.f32(hd.name, hd.w.n, hd.w.k)
485			if l.err != nil {
486				return l.err
487			}
488			put(hd.w.bank, hd.w.off, w, hd.w.n, hd.w.k)
489		}
490		// The tokenizer's audio_acoustic_proj (64 → 2048) and its pooler's
491		// embed_tokens (2048 → 2048) have nothing between them, so they are
492		// one [2048, 64] projection, folded in fp64 (the bias on the host).
493		{
494			H, L := g.enc.H, c.Latent
495			wp := l.f32("tokenizer.audio_acoustic_proj.weight", H, L)
496			we := l.f32("tokenizer.attention_pooler.embed_tokens.weight", H, H)
497			if l.err != nil {
498				return l.err
499			}
500			f := make([]float32, H*L)
501			parallel(H, func(o int) {
502				var acc [64]float64
503				for j := 0; j < H; j++ {
504					e := float64(we[o*H+j])
505					for i := 0; i < L; i++ {
506						acc[i] += e * float64(wp[j*L+i])
507					}
508				}
509				for i := 0; i < L; i++ {
510					f[o*L+i] = float32(acc[i])
511				}
512			})
513			put(g.tokIn.bank, g.tokIn.off, f, H, L)
514		}
515	
516		stageLayer := func(w layerW, d dims, p string, cross bool) error {
517			ps := selfProjs
518			if cross {
519				ps = append(append([]proj(nil), selfProjs...), crossProjs...)
520			}
521			for _, pr := range ps {
522				sh := g.projShape(d, pr)
523				wt := l.f32(p+projNames[pr]+".weight", sh[0], sh[1])
524				if l.err != nil {
525					return l.err
526				}
527				put(w.bank, w.off[pr], wt, sh[0], sh[1])
528			}
529			g.wbuf.WriteFloat32At(int(w.normQ), l.f32(p+"self_attn.q_norm.weight", headDim))
530			g.wbuf.WriteFloat32At(int(w.normK), l.f32(p+"self_attn.k_norm.weight", headDim))
531			if cross {
532				g.wbuf.WriteFloat32At(int(w.cnormQ), l.f32(p+"cross_attn.q_norm.weight", headDim))
533				g.wbuf.WriteFloat32At(int(w.cnormK), l.f32(p+"cross_attn.k_norm.weight", headDim))
534			}
535			return l.err
536		}
537		for i, w := range g.lyricL {
538			if err := stageLayer(w, g.enc, fmt.Sprintf("encoder.lyric_encoder.layers.%d.", i), false); err != nil {
539				return err
540			}
541		}
542		for i, w := range g.timbreL {
543			if err := stageLayer(w, g.enc, fmt.Sprintf("encoder.timbre_encoder.layers.%d.", i), false); err != nil {
544				return err
545			}
546		}
547		for i, w := range g.detokL {
548			if err := stageLayer(w, g.enc, fmt.Sprintf("detokenizer.layers.%d.", i), false); err != nil {
549				return err
550			}
551		}
552		for i, w := range g.poolL {
553			if err := stageLayer(w, g.enc, fmt.Sprintf("tokenizer.attention_pooler.layers.%d.", i), false); err != nil {
554				return err
555			}
556		}
557		for i, w := range g.ditL {
558			runtime.GC()
559			if err := stageLayer(w, g.dit, fmt.Sprintf("decoder.layers.%d.", i), true); err != nil {
560				return err
561			}
562		}
563		return nil
564	}
