566	// allocActivations places every activation, refuses a layout past the
567	// storage-buffer range (a buffer past it is clamped silently where it is
568	// bound), allocates, and fills the fp32 constants.
569	func (g *GPU) allocActivations(set *safetensors.Set) error {
570		c := g.cfg
571		alloc := func(n int) uint32 {
572			off := uint32(g.actElems)
573			g.actElems += roundUp(n, 64)
574			return off
575		}
576		R := g.rows
577		g.aX = alloc(R * max(g.dit.H, g.enc.H))
578		g.aS = alloc(R * max(g.dit.qW()+2*g.dit.kvW(), 2*g.dit.H+2*g.dit.ffn))
579		g.aMod = alloc(c.Layers * 6 * g.dit.H)
580		g.aTail = alloc(2 * g.dit.H)
581		g.aZeros = alloc(max(g.dit.H, g.enc.H))
582		g.aOnes = alloc(max(g.dit.H, g.enc.H))
583		g.aProjInB = alloc(g.dit.H)
584		g.aLyricB = alloc(g.enc.H)
585		g.aTimbreB = alloc(g.enc.H)
586		for i := range g.lyricL {
587			g.lyricL[i].norm1, g.lyricL[i].norm2 = alloc(g.enc.H), alloc(g.enc.H)
588		}
589		for i := range g.timbreL {
590			g.timbreL[i].norm1, g.timbreL[i].norm2 = alloc(g.enc.H), alloc(g.enc.H)
591		}
592		for i := range g.detokL {
593			g.detokL[i].norm1, g.detokL[i].norm2 = alloc(g.enc.H), alloc(g.enc.H)
594		}
595		g.aDetokNorm = alloc(g.enc.H)
596		for i := range g.poolL {
597			g.poolL[i].norm1, g.poolL[i].norm2 = alloc(g.enc.H), alloc(g.enc.H)
598		}
599		for i := range g.ditL {
600			g.ditL[i].crossNorm = alloc(g.dit.H)
601		}
602	
603		halloc := func(n int) uint32 {
604			off := uint32(g.hElems)
605			g.hElems += roundUp(n, 64)
606			return off
607		}
608		g.hQ = halloc(max(g.dit.heads, g.enc.heads) * R * headDim)
609		g.hK = halloc(max(g.dit.kv, g.enc.kv) * R * headDim)
610		g.hV = halloc(max(g.dit.kv, g.enc.kv) * R * headDim)
611		g.hA = halloc(R * max(g.dit.ldaH, g.enc.ldaH))
612		g.hCtx = halloc(R * max(g.dit.ldaQ, g.enc.ldaQ))
613		g.hFFN = halloc(R * max(g.dit.ldaFFN, g.enc.ldaFFN))
614		g.hIn = halloc(R * (max(c.PatchIn(), c.TextDim, c.TimbreDim, g.enc.H, g.dit.H) + gemmPad))
615		for i := range g.ditL {
616			g.ditL[i].crossK = halloc(g.dit.kv * g.encRows * headDim)
617			g.ditL[i].crossV = halloc(g.dit.kv * g.encRows * headDim)
618		}
619		for _, a := range []struct {
620			name  string
621			bytes int
622		}{{"fp32 activation", g.actElems * 4}, {"fp16 activation", g.hElems * 2}} {
623			if a.bytes > maxBankBytes {
624				return fmt.Errorf("dit: the %s arena for %d tokens is %d MB, past the %d MB storage-buffer range",
625					a.name, g.maxTokens, a.bytes>>20, maxBankBytes>>20)
626			}
627		}
628		var err error
629		if g.abuf, err = g.dev.NewBuffer(g.actElems * 4); err != nil {
630			return fmt.Errorf("dit: fp32 activation arena (%d MB): %w", (g.actElems*4)>>20, err)
631		}
632		if g.hbuf, err = g.dev.NewBuffer(g.hElems * 2); err != nil {
633			return fmt.Errorf("dit: fp16 activation arena (%d MB): %w", (g.hElems*2)>>20, err)
634		}
635		g.hbuf.ZeroUint16At(0, g.hElems)
636		g.abuf.ZeroFloat32At(0, g.actElems)
637		ones := make([]float32, max(g.dit.H, g.enc.H))
638		for i := range ones {
639			ones[i] = 1
640		}
641		g.abuf.WriteFloat32At(int(g.aOnes), ones)
642	
643		l := &loader{set: set}
644		g.abuf.WriteFloat32At(int(g.aProjInB), l.f32("decoder.proj_in.1.bias", g.dit.H))
645		g.abuf.WriteFloat32At(int(g.aLyricB), l.f32("encoder.lyric_encoder.embed_tokens.bias", g.enc.H))
646		g.abuf.WriteFloat32At(int(g.aTimbreB), l.f32("encoder.timbre_encoder.embed_tokens.bias", g.enc.H))
647		for _, st := range []struct {
648			ls []layerW
649			p  string
650		}{{g.lyricL, "encoder.lyric_encoder.layers.%d."}, {g.timbreL, "encoder.timbre_encoder.layers.%d."},
651			{g.detokL, "detokenizer.layers.%d."}, {g.poolL, "tokenizer.attention_pooler.layers.%d."}} {
652			for i, w := range st.ls {
653				p := fmt.Sprintf(st.p, i)
654				g.abuf.WriteFloat32At(int(w.norm1), l.f32(p+"input_layernorm.weight", g.enc.H))
655				g.abuf.WriteFloat32At(int(w.norm2), l.f32(p+"post_attention_layernorm.weight", g.enc.H))
656			}
657		}
658		g.abuf.WriteFloat32At(int(g.aDetokNorm), l.f32("detokenizer.norm.weight", g.enc.H))
659		for i, w := range g.ditL {
660			g.abuf.WriteFloat32At(int(w.crossNorm), l.f32(fmt.Sprintf("decoder.layers.%d.cross_attn_norm.weight", i), g.dit.H))
661		}
662		return l.err
663	}
