665	func (g *GPU) build(*safetensors.Set) error {
666		pcSize := uint32(unsafe.Sizeof(pushConstants{}))
667		base := []*vk.Buffer{g.wbuf, g.abuf, g.hbuf}
668		newPipe := func(spirv []byte, spec vk.PipelineSpec) (*vk.ComputePipeline, error) {
669			mod, err := g.dev.NewShaderModule(spirv)
670			if err != nil {
671				return nil, err
672			}
673			g.mods = append(g.mods, mod)
674			return g.dev.NewPipeline(mod, spec)
675		}
676		for name, spirv := range map[string][]byte{
677			"norm":   shaders.H3NormMod,
678			"qkpack": shaders.ACEQKPack,
679			"bias":   shaders.H3BiasCopy,
680			"pack":   shaders.DiTPackF16TPW8,
681			"gate":   shaders.DiTGateAdd,
682			"swiglu": shaders.DiTSwiGLUF16,
683		} {
684			p, err := newPipe(spirv, vk.PipelineSpec{Buffers: base, PushConstantSize: pcSize})
685			if err != nil {
686				return fmt.Errorf("dit: pipeline %s: %w", name, err)
687			}
688			g.pipes[name] = p
689		}
690		sgs, err := g.dev.Physical().SubgroupSizeControl()
691		if err != nil {
692			return err
693		}
694		if !g.dev.Features().SubgroupSizeControl || !sgs.Supported || 32 < sgs.MinSubgroupSize || 32 > sgs.MaxSubgroupSize {
695			return fmt.Errorf("dit: the attention builds need a pinned wave32")
696		}
697		for name, spirv := range map[string][]byte{
698			"attn full":   shaders.ACEAttnFull,
699			"attn window": shaders.ACEAttnWindow,
700			"attn cross":  shaders.ACEAttnCross,
701			"attn group":  shaders.ACEAttnGroup,
702		} {
703			p, err := newPipe(spirv, vk.PipelineSpec{Buffers: base, PushConstantSize: pcSize, RequiredSubgroupSize: 32})
704			if err != nil {
705				return fmt.Errorf("dit: pipeline %s: %w", name, err)
706			}
707			g.pipes[name] = p
708		}
709		for b := range g.banks {
710			m := map[gemmKernel]*vk.ComputePipeline{}
711			for k, v := range gemmVariants {
712				p, err := newPipe(v.spirv, vk.PipelineSpec{Buffers: []*vk.Buffer{g.wbuf, g.abuf, g.hbuf, g.banks[b]}, PushConstantSize: pcSize, RequiredSubgroupSize: v.wave})
713				if err != nil {
714					return fmt.Errorf("dit: gemm bank %d: %w", b, err)
715				}
716				m[k] = p
717			}
718			g.gemms = append(g.gemms, m)
719		}
720		return nil
721	}
