723	// Destroy releases every Vulkan object.
724	func (g *GPU) Destroy() {
725		for _, p := range g.pipes {
726			p.Destroy()
727		}
728		for _, m := range g.gemms {
729			for _, p := range m {
730				p.Destroy()
731			}
732		}
733		for _, m := range g.mods {
734			m.Destroy()
735		}
736		for _, b := range append([]*vk.Buffer{g.hbuf, g.abuf, g.wbuf}, g.banks...) {
737			if b != nil {
738				b.Destroy()
739			}
740		}
741	}
