757	// ---- the graph ------------------------------------------------------------
758	
759	type graph struct {
760		g     *GPU
761		d     []vk.MultiDispatch
762		kinds []string
763		flops []float64
764	}
765	
766	func (g *GPU) newGraph() *graph { return &graph{g: g} }
767	
768	func (gr *graph) add(pipe, kind string, gx, gy uint32, pc pushConstants, flops float64) {
769		gr.d = append(gr.d, vk.MultiDispatch{Pipeline: gr.g.pipes[pipe], GroupsX: gx, GroupsY: gy, PushConstants: pc.bytes()})
770		gr.kinds = append(gr.kinds, kind)
771		gr.flops = append(gr.flops, flops)
772	}
773	
774	// gemm issues C[mPad, n] fp32 at cOff (row stride n) = A[m, k] fp16 at aOff
775	// (row stride lda) × B, the fragment-tiled weight at bOff of bank.
776	func (gr *graph) gemm(kernel gemmKernel, bank int, kind string, aOff, cOff, bOff uint32, m, n, k, lda int) error {
777		if kernel == gemmBig && m <= bigW64Rows {
778			kernel = gemmBigW64
779		}
780		v := gemmVariants[kernel]
781		if n%v.bn != 0 || k%v.bk != 0 {
782			return fmt.Errorf("dit: %s: N=%d K=%d do not tile by %d/%d", kind, n, k, v.bn, v.bk)
783		}
784		mPad := roundUp(m, v.bm)
785		var pc pushConstants
786		pc.InOff, pc.OutOff, pc.BOff = aOff, cOff, bOff
787		pc.GemmM, pc.GemmN, pc.GemmK, pc.LDA = uint32(mPad), uint32(n), uint32(k), uint32(lda)
788		gr.d = append(gr.d, vk.MultiDispatch{Pipeline: gr.g.gemms[bank][kernel], GroupsX: uint32(n / v.bn), GroupsY: uint32(mPad / v.bm), PushConstants: pc.bytes()})
789		gr.kinds = append(gr.kinds, kind)
790		gr.flops = append(gr.flops, 2*float64(mPad)*float64(n)*float64(k))
791		return nil
792	}
793	
794	// A submission closes before its estimated device time passes the budget
795	// (amdgpu's 2 s ring watchdog; h3/dit's pricing).
796	const (
797		submitBudget = 800 * time.Millisecond
798		submitRate   = 12e12
799		submitFlat   = 2 * time.Millisecond
800	)
801	
802	func (gr *graph) submit() (time.Duration, error) {
803		var total time.Duration
804		for i := 0; i < len(gr.d); {
805			j, est := i, time.Duration(0)
806			for j < len(gr.d) {
807				c := submitFlat + time.Duration(gr.flops[j]/submitRate*1e9)
808				if j > i && est+c > submitBudget {
809					break
810				}
811				est += c
812				j++
813			}
814			if i > 0 && gr.g.Between != nil {
815				if err := gr.g.Between(); err != nil {
816					return total, err
817				}
818			}
819			t, err := vk.DispatchMultiTimed(gr.d[i:j], 1, 1, true)
820			if err != nil {
821				return total, fmt.Errorf("dit: dispatch %d-%d (%s): %w", i, j-1, gr.kinds[i], err)
822			}
823			total += t
824			i = j
825		}
826		gr.d, gr.kinds, gr.flops = gr.d[:0], gr.kinds[:0], gr.flops[:0]
827		return total, nil
828	}
829	
830	// norm records the modulated RMS pre-norm over rows [0, n) of the residual
831	// into hA: rms(x)·a + b.
832	func (gr *graph) norm(d dims, kind string, n int, a, b uint32) {
833		g := gr.g
834		var pc pushConstants
835		pc.Tokens, pc.Dim, pc.LDA = uint32(n), uint32(d.H), uint32(d.ldaH)
836		pc.InOff, pc.OutOff = g.aX, g.hA
837		pc.Aux0, pc.Aux1 = a, b
838		pc.Eps = math.Float32bits(float32(g.cfg.Eps))
839		gr.add("norm", kind, uint32(n), 1, pc, 0)
840	}
841	
842	// residual adds y (row stride d.H) into the residual, times the vector at
843	// gate unless gate is noGate.
844	func (gr *graph) residual(d dims, kind string, n int, y, gate uint32) {
845		var pc pushConstants
846		pc.Tokens, pc.Dim = uint32(n), uint32(d.H)
847		pc.InOff, pc.OutOff = y, gr.g.aX
848		if gate != noGate {
849			pc.Aux0, pc.Aux2 = gate, 1
850		}
851		gr.add("gate", kind, uint32(n), 1, pc, 0)
852	}
853	
854	const noGate = math.MaxUint32
855	
856	// qkpack records the per-head norm, the rotation and the scale of heads
857	// heads of width 128 at src (row stride heads·128) into the planes at dst
858	// (planeRows rows a plane).
859	func (gr *graph) qkpack(kind string, n, heads int, src, dst uint32, planeRows int, cos, sin, norm uint32, scale float32) {
860		tiles := roundUp(n, tile) / tile
861		var pc pushConstants
862		pc.Tokens, pc.Dim = uint32(n), uint32(heads*headDim)
863		pc.InOff, pc.OutOff = src, dst
864		pc.WOff, pc.Aux0 = cos, sin
865		pc.Aux1, pc.Aux2 = uint32(planeRows), norm
866		pc.Span, pc.Eps, pc.Scale = uint32(tiles), math.Float32bits(float32(gr.g.cfg.Eps)), math.Float32bits(scale)
867		gr.add("qkpack", kind, uint32((tiles+7)/8), uint32(heads), pc, 0)
868	}
869	
870	// vpack records v's narrowing into transposed fragment tiles.
871	func (gr *graph) vpack(kind string, n, heads int, src, dst uint32, planeRows int) {
872		tiles := roundUp(n, tile) / tile
873		var pc pushConstants
874		pc.Tokens, pc.Dim = uint32(n), uint32(heads*headDim)
875		pc.InOff, pc.OutOff = src, dst
876		pc.Aux0, pc.Aux1, pc.Aux2 = 1, uint32(planeRows), uint32(tiles)
877		pc.Scale = math.Float32bits(1)
878		gr.add("pack", kind, uint32((tiles+7)/8), uint32(heads), pc, 0)
879	}
880	
881	var qScale = float32(1/math.Sqrt(headDim)) * log2e
882	
883	// modVecs is where one layer's six vectors live in the fp32 arena: a1, b1,
884	// g1 before attention, a2, b2, g2 before the MLP. The encoders' gates are
885	// noGate.
886	type modVecs [6]uint32
887	
888	// layer records one transformer layer over rows [0, n) of the residual:
889	// self-attention (windowed on the even layers), cross-attention onto the
890	// request's condition planes when cross is set (the DiT), and the MLP.
891	func (gr *graph) layer(d dims, w layerW, n int, v modVecs, cross bool) error {
892		g := gr.g
893		R := g.rows
894		aQ := g.aS
895		aK := aQ + uint32(R*d.qW())
896		aV := aK + uint32(R*d.kvW())
897		aAttn := g.aS
898		aGate := aAttn + uint32(R*d.H)
899		aUp := aGate + uint32(R*d.ffn)
900		aFF := aUp + uint32(R*d.ffn)
901		nf := float64(n)
902	
903		cos, sin := g.wCos, g.wSin
904		switch w.group {
905		case 0:
906		case g.cfg.PoolWindow:
907			cos, sin = g.wCosG, g.wSinG
908		default:
909			cos, sin = g.wCosP, g.wSinP
910		}
911		gr.norm(d, "attn in", n, v[0], v[1])
912		for _, p := range []struct {
913			p   proj
914			out uint32
915		}{{pQ, aQ}, {pK, aK}, {pV, aV}} {
916			sh := g.projShape(d, p.p)
917			if err := gr.gemm(g.big, w.bank, "gemm qkv", g.hA, p.out, w.off[p.p], n, sh[0], sh[1], d.ldaH); err != nil {
918				return err
919			}
920		}
921		gr.qkpack("qkpack q", n, d.heads, aQ, g.hQ, R, cos, sin, w.normQ, qScale)
922		gr.qkpack("qkpack k", n, d.kv, aK, g.hK, R, cos, sin, w.normK, 1)
923		gr.vpack("pack v", n, d.kv, aV, g.hV, R)
924		{
925			var pc pushConstants
926			pc.Tokens, pc.Heads = uint32(n), uint32(d.heads)
927			pc.InOff, pc.KOff, pc.VOff = g.hQ, g.hK, g.hV
928			pc.OutOff, pc.LDA = g.hCtx, uint32(d.ldaQ)
929			pc.Aux1, pc.Aux2 = uint32(R), uint32(d.heads/d.kv)
930			pipe, keys := "attn full", nf
931			if w.window {
932				pipe, pc.Span = "attn window", uint32(g.cfg.Window)
933				keys = math.Min(nf, float64(2*g.cfg.Window+1))
934			}
935			if w.group > 0 {
936				pipe, pc.Span = "attn group", uint32(w.group)
937				keys = float64(w.group)
938			}
939			gr.add(pipe, "attention", uint32((n+tile-1)/tile), uint32(d.heads), pc, 4*nf*keys*headDim*float64(d.heads))
940		}
941		if err := gr.gemm(g.big, w.bank, "gemm o", g.hCtx, aAttn, w.off[pO], n, d.H, d.qW(), d.ldaQ); err != nil {
942			return err
943		}
944		gr.residual(d, "gate attn", n, aAttn, v[2])
945	
946		if cross {
947			gr.norm(d, "cross in", n, w.crossNorm, g.aZeros)
948			if err := gr.gemm(g.big, w.bank, "gemm cross q", g.hA, aQ, w.off[pCQ], n, d.qW(), d.H, d.ldaH); err != nil {
949				return err
950			}
951			gr.qkpack("qkpack cross q", n, d.heads, aQ, g.hQ, R, g.wCosID, g.wSinID, w.cnormQ, qScale)
952			var pc pushConstants
953			pc.Tokens, pc.KStride, pc.Heads = uint32(g.encLen), uint32(n), uint32(d.heads)
954			pc.InOff, pc.KOff, pc.VOff = g.hQ, w.crossK, w.crossV
955			pc.OutOff, pc.LDA = g.hCtx, uint32(d.ldaQ)
956			pc.Aux1, pc.Aux2, pc.LDB = uint32(R), uint32(d.heads/d.kv), uint32(g.encRows)
957			gr.add("attn cross", "cross attention", uint32((n+tile-1)/tile), uint32(d.heads), pc,
958				4*nf*float64(g.encLen)*headDim*float64(d.heads))
959			if err := gr.gemm(g.big, w.bank, "gemm cross o", g.hCtx, aAttn, w.off[pCO], n, d.H, d.qW(), d.ldaQ); err != nil {
960				return err
961			}
962			gr.residual(d, "cross add", n, aAttn, noGate)
963		}
964	
965		gr.norm(d, "ffn in", n, v[3], v[4])
966		if err := gr.gemm(g.big, w.bank, "gemm gate", g.hA, aGate, w.off[pGate], n, d.ffn, d.H, d.ldaH); err != nil {
967			return err
968		}
969		if err := gr.gemm(g.big, w.bank, "gemm up", g.hA, aUp, w.off[pUp], n, d.ffn, d.H, d.ldaH); err != nil {
970			return err
971		}
972		var pc pushConstants
973		pc.Tokens, pc.Dim, pc.LDA = uint32(n), uint32(d.ffn), uint32(d.ldaFFN)
974		pc.InOff, pc.KOff, pc.OutOff = aGate, aUp, g.hFFN
975		pc.Scale = math.Float32bits(1)
976		gr.add("swiglu", "swiglu", uint32(n), 1, pc, 0)
977		if err := gr.gemm(g.big, w.bank, "gemm down", g.hFFN, aFF, w.off[pDown], n, d.H, d.ffn, d.ldaFFN); err != nil {
978			return err
979		}
980		gr.residual(d, "gate ffn", n, aFF, v[5])
981		return nil
982	}
983	
984	// zeroKeyTail zeroes k and v plane rows between the last tile a pack of
985	// keys rows writes and the end of the last key block the attention reads,
986	// in every plane at base (heads of them, planeRows rows each): a stale key
987	// from a longer sequence is masked, but a masked fp16 product still carries
988	// its sign into the sum (WMMA's -0), so the tail is made the same every time.
989	func (g *GPU) zeroKeyTail(bases []uint32, heads, planeRows, keys int) {
990		from, to := roundUp(keys, tile), min(roundUp(keys, maxKeyBlock), planeRows)
991		if from >= to {
992			return
993		}
994		for _, b := range bases {
995			for h := 0; h < heads; h++ {
996				g.hbuf.ZeroUint16At(int(b)+(h*planeRows+from)*headDim, (to-from)*headDim)
997			}
998		}
999	}
1000	
1001	// narrowRows writes an fp32 host matrix as an fp16 A operand with row
1002	// stride lda at hOff.
1003	func (g *GPU) narrowRows(hOff uint32, m *qwen.Mat, lda int) {
1004		buf := make([]uint16, m.Rows*lda)
1005		parallel(m.Rows, func(r int) {
1006			for c, v := range m.Row(r) {
1007				buf[r*lda+c] = safetensors.F32ToF16(v)
1008			}
1009		})
1010		g.hbuf.WriteUint16At(int(hOff), buf)
1011	}
1012	
1013	func (g *GPU) readX(rows, cols int) *qwen.Mat {
1014		m := qwen.NewMat(rows, cols)
1015		copy(m.Data, g.abuf.ReadFloat32At(int(g.aX), rows*cols))
1016		return m
1017	}
1018	
1019	// ---- the condition encoder (A2) --------------------------------------------
1020	
1021	// Stack names one of the three stacks, for the per-layer instruments.
1022	type Stack int
1023	
1024	const (
1025		Lyric Stack = iota
1026		Timbre
1027		DiT
1028	)
1029	
1030	func (g *GPU) stack(s Stack) ([]layerW, dims) {
1031		switch s {
1032		case Lyric:
1033			return g.lyricL, g.enc
1034		case Timbre:
1035			return g.timbreL, g.enc
1036		default:
1037			return g.ditL, g.dit
1038		}
1039	}
1040	
1041	// encoderLayers records layers [from, to) of an encoder over n rows.
1042	func (gr *graph) encoderLayers(ls []layerW, n, from, to int) error {
1043		g := gr.g
1044		g.zeroKeyTail([]uint32{g.hK, g.hV}, g.enc.kv, g.rows, n)
1045		for i := from; i < to; i++ {
1046			w := ls[i]
1047			v := modVecs{w.norm1, g.aZeros, noGate, w.norm2, g.aZeros, noGate}
1048			if err := gr.layer(g.enc, w, n, v, false); err != nil {
1049				return err
1050			}
1051		}
1052		return nil
1053	}
1054	
1055	// EncoderLayers runs layers [from, to) of the lyric or timbre encoder over
1056	// x, their residual stream, and returns it after them: the teacher-forced
1057	// instrument the A2 gates run layer by layer.
1058	func (g *GPU) EncoderLayers(s Stack, x *qwen.Mat, from, to int) (*qwen.Mat, error) {
1059		ls, d := g.stack(s)
1060		if s == DiT || x.Cols != d.H || x.Rows > g.rows {
1061			return nil, fmt.Errorf("dit: encoder residual %v", x)
1062		}
1063		g.abuf.WriteFloat32At(int(g.aX), x.Data)
1064		gr := g.newGraph()
1065		if err := gr.encoderLayers(ls, x.Rows, from, to); err != nil {
1066			return nil, err
1067		}
1068		if _, err := gr.submit(); err != nil {
1069			return nil, err
1070		}
1071		return g.readX(x.Rows, d.H), nil
1072	}
1073	
1074	// embedInto records an input projection of an fp16 operand (m rows at hIn,
1075	// row stride k+pad) into the residual from row dst, plus its bias.
1076	func (gr *graph) embedInto(hw headW, m, dst int, bias uint32) error {
1077		g := gr.g
1078		out := g.aX + uint32(dst*hw.n)
1079		if err := gr.gemm(g.big, hw.bank, "gemm embed", g.hIn, out, hw.off, m, hw.n, hw.k, hw.k+gemmPad); err != nil {
1080			return err
1081		}
1082		var pc pushConstants
1083		pc.Tokens, pc.Dim, pc.LDA = uint32(m), uint32(hw.n), uint32(hw.n)
1084		pc.InOff, pc.OutOff = out, out
1085		pc.Aux0, pc.Aux2 = bias, 1
1086		gr.add("bias", "bias", uint32(m), 1, pc, 0)
1087		return nil
1088	}
1089	
1090	// Encode runs the condition encoder: text is Qwen3-Embedding's last hidden
1091	// state over the caption prompt [Lt, 1024], lyric the embedding table's rows
1092	// for the lyric prompt [Ll, 1024], timbre the reference latents [750, 64]
1093	// (silence_latent[:750] when there is none). It returns the packed
1094	// cross-attention sequence [Ll + 1 + Lt, 2048]: lyric encoder, timbre CLS,
1095	// projected text. The final norms run on the host in fp32.
1096	func (g *GPU) Encode(text, lyric, timbre *qwen.Mat) (*qwen.Mat, error) {
1097		c := g.cfg
1098		if text.Cols != c.TextDim || lyric.Cols != c.TextDim || timbre.Cols != c.TimbreDim ||
1099			text.Rows > MaxTextTokens || lyric.Rows > MaxLyricTokens || timbre.Rows+1 > g.rows || lyric.Rows == 0 || text.Rows == 0 {
1100			return nil, fmt.Errorf("dit: encoder inputs text %v lyric %v timbre %v", text, lyric, timbre)
1101		}
1102		H := g.enc.H
1103		// The caption: text_projector alone, into the scratch.
1104		g.narrowRows(g.hIn, text, c.TextDim+gemmPad)
1105		gr := g.newGraph()
1106		if err := gr.gemm(g.big, g.textProj.bank, "gemm text", g.hIn, g.aS, g.textProj.off, text.Rows, H, c.TextDim, c.TextDim+gemmPad); err != nil {
1107			return nil, err
1108		}
1109		if _, err := gr.submit(); err != nil {
1110			return nil, err
1111		}
1112		txt := g.abuf.ReadFloat32At(int(g.aS), text.Rows*H)
1113	
1114		// The lyrics: embed_tokens, 8 layers, the final norm.
1115		g.narrowRows(g.hIn, lyric, c.TextDim+gemmPad)
1116		if err := gr.embedInto(g.lyricIn, lyric.Rows, 0, g.aLyricB); err != nil {
1117			return nil, err
1118		}
1119		if err := gr.encoderLayers(g.lyricL, lyric.Rows, 0, len(g.lyricL)); err != nil {
1120			return nil, err
1121		}
1122		if _, err := gr.submit(); err != nil {
1123			return nil, err
1124		}
1125		lyr, err := g.Host.LyricNorm.Apply(g.readX(lyric.Rows, H))
1126		if err != nil {
1127			return nil, err
1128		}
1129	
1130		// The timbre: CLS then embed_tokens(latents), 4 layers, the CLS row.
1131		n := timbre.Rows + 1
1132		g.narrowRows(g.hIn, timbre, c.TimbreDim+gemmPad)
1133		g.abuf.WriteFloat32At(int(g.aX), g.Host.TimbreCLS)
1134		if err := gr.embedInto(g.timbreIn, timbre.Rows, 1, g.aTimbreB); err != nil {
1135			return nil, err
1136		}
1137		if err := gr.encoderLayers(g.timbreL, n, 0, len(g.timbreL)); err != nil {
1138			return nil, err
1139		}
1140		if _, err := gr.submit(); err != nil {
1141			return nil, err
1142		}
1143		cls, err := g.Host.TimbreNorm.Apply(g.readX(1, H))
1144		if err != nil {
1145			return nil, err
1146		}
1147	
1148		out := qwen.NewMat(lyric.Rows+1+text.Rows, H)
1149		copy(out.Data, lyr.Data)
1150		copy(out.Row(lyric.Rows), cls.Data)
1151		copy(out.Data[(lyric.Rows+1)*H:], txt)
1152		return out, nil
1153	}
1154	
1155	// ---- the DiT (A3) ------------------------------------------------------------
1156	
1157	// Begin prepares a request's cross-attention: enc, the packed condition
1158	// sequence [L, 2048], through condition_embedder, then every layer's
1159	// cross-attention keys (k_proj, k_norm, no rotation) and values into that
1160	// layer's planes.
1161	func (g *GPU) Begin(enc *qwen.Mat) error {
1162		if enc.Cols != g.enc.H || enc.Rows > g.maxEnc || enc.Rows == 0 {
1163			return fmt.Errorf("dit: condition sequence %v, staged for %d rows", enc, g.maxEnc)
1164		}
1165		L, H := enc.Rows, g.dit.H
1166		g.narrowRows(g.hIn, enc, g.enc.H+gemmPad)
1167		gr := g.newGraph()
1168		if err := gr.gemm(g.big, g.condEmb.bank, "gemm condition", g.hIn, g.aS, g.condEmb.off, L, H, g.enc.H, g.enc.H+gemmPad); err != nil {
1169			return err
1170		}
1171		if _, err := gr.submit(); err != nil {
1172			return err
1173		}
1174		ce := qwen.NewMat(L, H)
1175		copy(ce.Data, g.abuf.ReadFloat32At(int(g.aS), L*H))
1176		for r := 0; r < L; r++ {
1177			row := ce.Row(r)
1178			for i := range row {
1179				row[i] += g.Host.CondB[i]
1180			}
1181		}
1182		g.narrowRows(g.hIn, ce, H+gemmPad)
1183		aK := g.aS
1184		aV := aK + uint32(g.encRows*g.dit.kvW())
1185		kv := g.dit.kvW()
1186		for _, w := range g.ditL {
1187			g.zeroKeyTail([]uint32{w.crossK, w.crossV}, g.dit.kv, g.encRows, L)
1188			if err := gr.gemm(g.big, w.bank, "gemm cross k", g.hIn, aK, w.off[pCK], L, kv, H, H+gemmPad); err != nil {
1189				return err
1190			}
1191			if err := gr.gemm(g.big, w.bank, "gemm cross v", g.hIn, aV, w.off[pCV], L, kv, H, H+gemmPad); err != nil {
1192				return err
1193			}
1194			gr.qkpack("qkpack cross k", L, g.dit.kv, aK, w.crossK, g.encRows, g.wCosID, g.wSinID, w.cnormK, 1)
1195			gr.vpack("pack cross v", L, g.dit.kv, aV, w.crossV, g.encRows)
1196		}
1197		if _, err := gr.submit(); err != nil {
