959			pc.InOff, pc.OutOff, pc.BOff = aOff, cOff, bOff
960			pc.GemmM, pc.GemmN, pc.GemmK, pc.LDA = uint32(mPad), uint32(n), uint32(k), uint32(lda)
961			pc.Aux0, pc.Aux1 = uint32(k0), uint32(k1)
