972	// submitBudget is how much estimated device time one submission may hold.
973	// amdgpu kills a submission that holds the ring for 2 s (research/p0-ring-
974	// watchdog.md), and a count of dispatches is no bound: one block's five
975	// attention chunks at 38k rows are 2.15 s. Each dispatch is priced at its
976	// FLOPs over submitRate — below what any matrix-core kernel here measures —
977	// plus a flat cost for the elementwise passes, and a submission closes
978	// before it would pass the budget. A dispatch priced over the budget on its
979	// own still goes, alone; NewGPU's chunk is what keeps those under 2 s.
980	const (
981		submitBudget = 800 * time.Millisecond
982		submitRate   = 12e12
983		submitFlat   = 2 * time.Millisecond
984	)
985	
986	func (gr *graph) submit() (time.Duration, error) {
987		var total time.Duration
988		for i := 0; i < len(gr.d); {
989			j, est := i, time.Duration(0)
990			for j < len(gr.d) {
991				c := submitFlat + time.Duration(gr.flops[j]/submitRate*1e9)
992				if j > i && est+c > submitBudget {
993					break
994				}
995				est += c
996				j++
997			}
998			if i > 0 && gr.g.Between != nil {
999				if err := gr.g.Between(); err != nil {
1000					return total, err
1001				}
1002			}
1003			t, err := vk.DispatchMultiTimed(gr.d[i:j], 1, 1, true)
1004			if err != nil {
1005				return total, fmt.Errorf("dit: dispatch %d-%d (%s): %w", i, j-1, gr.kinds[i], err)
1006			}
1007			total += t
1008			i = j
1009		}
1010		gr.d, gr.kinds, gr.flops = gr.d[:0], gr.kinds[:0], gr.flops[:0]
1011		return total, nil
1012	}
