1036		norm := func(kind string, r0, r1, which int) {
1037			for _, ru := range runs {
1038				lo, hi := max(ru.start, r0), min(ru.start+ru.n, r1)
1039				if lo >= hi {
1040					continue
1041				}
1042				v := vecs[ru.key]
1043				pc := gr.base
1044				pc.Tokens, pc.Dim, pc.LDA = uint32(hi-lo), uint32(g.H), uint32(g.ldaH)
1045				pc.InOff = g.aX + uint32(lo*g.H)
