1056				}
1057				pc := gr.base
1058				pc.Tokens, pc.Dim = uint32(hi-lo), uint32(g.H)
1059				pc.InOff = y + uint32((lo-r0)*g.H)
1060				pc.OutOff = g.aX + uint32(lo*g.H)
