1465	
1466	// Tokenize turns 25 Hz latents [T, 64] (T a multiple of 5: upstream pads
1467	// with the silence latent first) into 5 Hz audio codes, as upstream's
1468	// tokenize does for a cover's source: audio_acoustic_proj and the pooler's
1469	// embed_tokens (one folded projection), a CLS row before every 5 latents,
1470	// the pooler's two layers over each 6-row group (the GROUP attention), the
1471	// final norm on the CLS rows, and the FSQ on the host. It also returns the
1472	// pooled rows (the FSQ's input, [T/5, 2048]) and each code's margin from a
1473	// quantisation boundary (plan.FSQIndex), for the gates.
1474	func (g *GPU) Tokenize(lat *qwen.Mat) (codes []int32, pooled *qwen.Mat, margins []float32, err error) {
1475		c := g.cfg
1476		h := g.Host
1477		H, P := g.enc.H, c.PoolWindow
1478		G := P + 1
1479		if lat.Cols != c.Latent || lat.Rows == 0 || lat.Rows%P != 0 {
1480			return nil, nil, nil, fmt.Errorf("dit: tokenizer input %v, want rows a multiple of %d", lat, P)
1481		}
1482		groups := lat.Rows / P
1483		pooled = qwen.NewMat(groups, H)
1484		codes = make([]int32, groups)
1485		margins = make([]float32, groups)
1486		chunk := g.rows / G
1487		for c0 := 0; c0 < groups; c0 += chunk {
1488			cs := min(chunk, groups-c0)
1489			in := &qwen.Mat{Rows: cs * P, Cols: c.Latent, Data: lat.Data[c0*P*c.Latent : (c0+cs)*P*c.Latent]}
1490			g.narrowRows(g.hIn, in, c.Latent+gemmPad)
1491			gr := g.newGraph()
1492			if err := gr.gemm(g.big, g.tokIn.bank, "gemm tok embed", g.hIn, g.aS, g.tokIn.off, cs*P, H, c.Latent, c.Latent+gemmPad); err != nil {
1493				return nil, nil, nil, err
1494			}
1495			if _, err := gr.submit(); err != nil {
1496				return nil, nil, nil, err
1497			}
1498			e := g.abuf.ReadFloat32At(int(g.aS), cs*P*H)
1499			n := cs * G
1500			x := make([]float32, n*H)
1501			parallel(cs, func(i int) {
1502				copy(x[i*G*H:], h.PoolSpecial)
1503				for p := 0; p < P; p++ {
1504					row := x[(i*G+1+p)*H : (i*G+2+p)*H]
1505					src := e[(i*P+p)*H:]
1506					for j := range row {
1507						row[j] = src[j] + h.TokB[j]
1508					}
1509				}
1510			})
1511			g.abuf.WriteFloat32At(int(g.aX), x)
1512			if err := gr.encoderLayers(g.poolL, n, 0, len(g.poolL)); err != nil {
1513				return nil, nil, nil, err
1514			}
1515			if _, err := gr.submit(); err != nil {
1516				return nil, nil, nil, err
1517			}
1518			all := g.abuf.ReadFloat32At(int(g.aX), n*H)
1519			cls := qwen.NewMat(cs, H)
1520			for i := 0; i < cs; i++ {
1521				copy(cls.Row(i), all[i*G*H:(i*G+1)*H])
1522			}
1523			normed, err := h.PoolNorm.Apply(cls)
1524			if err != nil {
1525				return nil, nil, nil, err
1526			}
1527			copy(pooled.Data[c0*H:], normed.Data)
1528			for i := 0; i < cs; i++ {
1529				row := normed.Row(i)
1530				var z [6]float32
1531				for d := range z {
1532					s := float64(h.FSQInB[d])
1533					for j, v := range h.FSQInW[d*H : (d+1)*H] {
1534						s += float64(v) * float64(row[j])
1535					}
1536					z[d] = float32(s)
1537				}
1538				idx, m := plan.FSQIndex(z)
1539				codes[c0+i], margins[c0+i] = int32(idx), m
1540			}
1541		}
1542		return codes, pooled, margins, nil
1543	}

