92	// relGap is the max abs error over the reference's absmax, and the rms
93	// error over the reference's rms.
94	func relGap(got, want *qwen.Mat) (rel, rmsRel float64) {
95		var maxAbs, ref, sq, refSq float64
96		for i := range want.Data {
97			d := math.Abs(float64(got.Data[i]) - float64(want.Data[i]))
98			maxAbs = math.Max(maxAbs, d)
99			ref = math.Max(ref, math.Abs(float64(want.Data[i])))
100			sq += d * d
101			refSq += float64(want.Data[i]) * float64(want.Data[i])
102		}
103		return maxAbs / ref, math.Sqrt(sq / refSq)
104	}
