109			t.Fatalf("%s: %v, want %v", name, got, want)
110		}
111		for _, v := range got.Data {
112			if math.IsNaN(float64(v)) || math.IsInf(float64(v), 0) {
113				t.Fatalf("%s: non-finite output", name)
114			}
115		}
116		rel, rms := relGap(got, want)
117		t.Logf("%-28s max %.2e  rms %.2e", name, rel, rms)
118		if rel > maxRel || rms > maxRMS {
119			t.Errorf("%s: max %.2e (limit %.0e), rms %.2e (limit %.0e)", name, rel, maxRel, rms, maxRMS)
120		}
121		return rms
122	}
