355	func TestGPUStepTiming(t *testing.T) {
356		g := sharedGPU(t)
357		loadDitManifest(t)
358		// ACE_DIT_BIG=w64|small runs the big projections on the wave64 128x256
359		// build or the 64x64 rung instead (KERNELS.md G8's small-M screen).
360		switch os.Getenv("ACE_DIT_BIG") {
361		case "w64":
362			g.big = gemmBigW64
