371			T := sec * 25
372			x, ctx := qwen.NewMat(T, 64), qwen.NewMat(T, 128)
373			for i := range x.Data {
374				x.Data[i] = float32(math.Sin(float64(i)))
375			}
376			var best time.Duration
377			for r := 0; r < 3; r++ {
378				_, took, err := g.Step(x, ctx, 0.75)
379				if err != nil {
