397			for _, s := range st {
398				by[s.Kind] += s.GPU
399				fl[s.Kind] += s.Flops
400				total += s.GPU
401			}
402			kinds := make([]string, 0, len(by))
403			for k := range by {
404				kinds = append(kinds, k)
405			}
406			sort.Slice(kinds, func(i, j int) bool { return by[kinds[i]] > by[kinds[j]] })
407			for _, k := range kinds {
408				tf := ""
409				if fl[k] > 0 {
