494			for i := 0; i < H; i++ {
495				s += float64(po[o*H+i]) * float64(nb[i])
496			}
497			g.outBias[o] = float32(s)
498		}
499		put(g.projOut.bank, g.projOut.off, po, c.PatchOut(), H)
500		g.abuf.WriteFloat32At(int(g.aNormOut), nw)
501	
502		for i, bw := range g.blocks {
503			p := fmt.Sprintf("decoder.transformer_blocks.%d.", i)
504			get := func(name string, n int) []float32 {
505				if err != nil {
506					return nil
507				}
508				var v []float32
509				v, err = f32(set, p+name, n)
510				return v
511			}
512			wq, bq := get("attn.to_q.weight", H*H), get("attn.to_q.bias", H)
513			wk, bk := get("attn.to_k.weight", H*H), get("attn.to_k.bias", H)
514			wv, bv := get("attn.to_v.weight", H*H), get("attn.to_v.bias", H)
515			wo, bo := get("attn.to_out.0.weight", H*H), get("attn.to_out.0.bias", H)
516			up, bup := get("ff.net.0.proj.weight", 2*g.ffn*H), get("ff.net.0.proj.bias", 2*g.ffn)
517			down, bdown := get("ff.net.2.weight", H*g.ffn), get("ff.net.2.bias", H)
518			n1, n2 := get("norm1.weight", H), get("norm2.weight", H)
519			s1, s2 := get("scale1", H), get("scale2", H)
520			if err != nil {
521				return err
522			}
523			// SwiGLU is value·silu(gate) with the projection's rows [value | gate].
524			lin := map[proj][2][]float32{
525				projQ: {wq, bq}, projK: {wk, bk}, projV: {wv, bv}, projO: {wo, bo},
526				projUp: {up[:g.ffn*H], bup[:g.ffn]}, projGate: {up[g.ffn*H:], bup[g.ffn:]},
527				projDown: {down, bdown},
528			}
529			for _, pr := range projOrder {
530				n, k := g.projShape(pr)
531				realK := g.H
532				if pr == projDown {
533					realK = g.ffn
534				}
535				put(bw.bank, bw.off[pr], withBias(lin[pr][0], lin[pr][1], n, realK, k), n, k)
536			}
537			g.abuf.WriteFloat32At(int(bw.norm1), n1)
538			g.abuf.WriteFloat32At(int(bw.norm2), n2)
539			g.abuf.WriteFloat32At(int(bw.s1), s1)
540			g.abuf.WriteFloat32At(int(bw.s2), s2)
541		}
542		return nil
543	}
