545	func (g *GPU) build(*safetensors.Set) error {
546		pcSize := uint32(unsafe.Sizeof(pushConstants{}))
547		base := []*vk.Buffer{g.wbuf, g.abuf, g.hbuf}
548		newPipe := func(spirv []byte, spec vk.PipelineSpec) (*vk.ComputePipeline, error) {
549			mod, err := g.dev.NewShaderModule(spirv)
550			if err != nil {
551				return nil, err
552			}
553			g.mods = append(g.mods, mod)
554			return g.dev.NewPipeline(mod, spec)
555		}
556		for name, spirv := range map[string][]byte{
557			"norm":      shaders.H3NormMod,
558			"qkpack":    shaders.H3VAEQKPackHD64,
559			"pack":      shaders.H3VAEPackHD64,
560			"gate":      shaders.DiTGateAdd,
561			"swiglu":    shaders.DiTSwiGLUF16,
562			"finalnorm": shaders.DiTFinalNorm,
563		} {
564			p, err := newPipe(spirv, vk.PipelineSpec{Buffers: base, PushConstantSize: pcSize})
565			if err != nil {
566				return fmt.Errorf("vae: pipeline %s: %w", name, err)
567			}
568			g.pipes[name] = p
569		}
570		sgs, err := g.dev.Physical().SubgroupSizeControl()
571		if err != nil {
572			return err
573		}
574		if !g.dev.Features().SubgroupSizeControl || !sgs.Supported || 32 < sgs.MinSubgroupSize || 32 > sgs.MaxSubgroupSize {
575			return fmt.Errorf("vae: the attention build needs a pinned wave32")
576		}
577		g.attnPipes = map[AttnVariant]*vk.ComputePipeline{}
578		for v, spirv := range attnBuilds {
579			p, err := newPipe(spirv, vk.PipelineSpec{Buffers: base, PushConstantSize: pcSize, RequiredSubgroupSize: 32})
580			if err != nil {
581				return fmt.Errorf("vae: attention pipeline %v: %w", v, err)
582			}
583			g.attnPipes[v] = p
584		}
585		g.attn = attnPlain
586		for b := range g.banks {
587			m := map[gemmKernel]*vk.ComputePipeline{}
588			for k, v := range gemmVariants {
589				p, err := newPipe(v.spirv, vk.PipelineSpec{Buffers: []*vk.Buffer{g.wbuf, g.abuf, g.hbuf, g.banks[b]}, PushConstantSize: pcSize, RequiredSubgroupSize: v.wave})
590				if err != nil {
591					return fmt.Errorf("vae: gemm bank %d: %w", b, err)
592				}
593				m[k] = p
594			}
595			g.gemms = append(g.gemms, m)
596		}
597		return nil
598	}
