634	// graph accumulates one batch's dispatches.
635	type graph struct {
636		g     *GPU
637		d     []vk.MultiDispatch
638		kinds []string
639		flops []float64
640		base  pushConstants
641	}
642	
643	func (g *GPU) newGraph() *graph {
644		return &graph{g: g, base: pushConstants{Heads: uint32(g.heads), HeadDim: uint32(g.headDim)}}
645	}
646	
647	func (gr *graph) add(pipe *vk.ComputePipeline, kind string, gx, gy uint32, pc pushConstants, flops float64) {
648		gr.d = append(gr.d, vk.MultiDispatch{Pipeline: pipe, GroupsX: gx, GroupsY: gy, PushConstants: pc.bytes()})
649		gr.kinds = append(gr.kinds, kind)
650		gr.flops = append(gr.flops, flops)
651	}
