653	// gemm issues C[mPad, n] fp32 at cOff = A[m, k] fp16 at aOff (row stride
654	// lda) × B, the fragment-tiled weight at bOff of bank.
655	func (gr *graph) gemm(kernel gemmKernel, bank int, kind string, aOff, cOff, bOff uint32, m, n, k, lda int) error {
656		v := gemmVariants[kernel]
657		if n%v.bn != 0 || k%v.bk != 0 {
658			return fmt.Errorf("vae: %s: N=%d K=%d do not tile by %d/%d", kind, n, k, v.bn, v.bk)
659		}
660		mPad := roundUp(m, v.bm)
661		pc := gr.base
662		pc.InOff, pc.OutOff, pc.BOff = aOff, cOff, bOff
663		pc.GemmM, pc.GemmN, pc.GemmK, pc.LDA = uint32(mPad), uint32(n), uint32(k), uint32(lda)
664		gr.add(gr.g.gemms[bank][kernel], kind, uint32(n/v.bn), uint32(mPad/v.bm), pc, 2*float64(mPad)*float64(n)*float64(k))
665		return nil
666	}
