668	// submitBudget and the rest are M7's guard against the 2-second ring
669	// watchdog (research/p0-ring-watchdog.md): a submission closes before its
670	// estimated device time passes the budget.
671	const (
672		submitBudget = 800 * time.Millisecond
673		submitRate   = 12e12
674		submitFlat   = 2 * time.Millisecond
675	)
676	
677	func (gr *graph) submit() (time.Duration, error) {
678		var total time.Duration
679		for i := 0; i < len(gr.d); {
680			j, est := i, time.Duration(0)
681			for j < len(gr.d) {
682				c := submitFlat + time.Duration(gr.flops[j]/submitRate*1e9)
683				if j > i && est+c > submitBudget {
684					break
685				}
686				est += c
687				j++
688			}
689			if i > 0 && gr.g.Between != nil {
690				if err := gr.g.Between(); err != nil {
691					return total, err
692				}
693			}
694			t, err := vk.DispatchMultiTimed(gr.d[i:j], 1, 1, true)
695			if err != nil {
696				return total, fmt.Errorf("vae: dispatch %d-%d (%s): %w", i, j-1, gr.kinds[i], err)
697			}
698			total += t
699			i = j
700		}
701		gr.d, gr.kinds, gr.flops = gr.d[:0], gr.kinds[:0], gr.flops[:0]
702		return total, nil
703	}
