705	// blockPass records one block over seqs sequences.
706	func (gr *graph) blockPass(w blockW, seqs int) error {
707		g := gr.g
708		rows := seqs * g.stride
709		eps := math.Float32bits(float32(g.cfg.NormEps))
710		// The GEMMs write whole 128-row tiles, so the scratch's regions are
711		// spaced by the padded row count and none spills into the next.
712		pad := roundUp(rows, rowAlign)
713		aQ := g.aS
714		aK := aQ + uint32(pad*g.H)
715		aV := aK + uint32(pad*g.H)
716		aAttn := g.aS
717		aGate := aAttn + uint32(pad*g.H)
718		aUp := aGate + uint32(pad*g.ffn)
719		aFF := aUp + uint32(pad*g.ffn)
720	
721		norm := func(kind string, weight uint32) {
722			pc := gr.base
723			pc.Tokens, pc.Dim, pc.LDA = uint32(rows), uint32(g.H), uint32(g.ldaH)
724			pc.InOff, pc.OutOff = g.aX, g.hA
725			pc.Aux0, pc.Aux1, pc.Eps = weight, g.aZeros, eps
726			gr.add(g.pipes["norm"], kind, uint32(rows), 1, pc, 0)
727		}
728		gate := func(kind string, y, vec uint32) {
729			pc := gr.base
730			pc.Tokens, pc.Dim = uint32(rows), uint32(g.H)
731			pc.InOff, pc.OutOff = y, g.aX
732			pc.Aux0, pc.Aux2 = vec, 1
733			gr.add(g.pipes["gate"], kind, uint32(rows), 1, pc, 0)
734		}
735	
736		norm("attn in", w.norm1)
737		for _, pr := range []struct {
738			p   proj
739			out uint32
740		}{{projQ, aQ}, {projK, aK}, {projV, aV}} {
741			if err := gr.gemm(gemmBig, w.bank, "gemm qkv", g.hA, pr.out, w.off[pr.p], rows, g.H, g.kH, g.ldaH); err != nil {
742				return err
743			}
744		}
745		tiles := rows / tile
746		for _, qk := range []struct {
747			kind     string
748			src, dst uint32
749			scale    float32
750		}{
751			{"qkpack q", aQ, g.hQ, float32(1/math.Sqrt(float64(g.headDim))) * log2e},
752			{"qkpack k", aK, g.hK, 1},
753		} {
754			pc := gr.base
755			pc.Tokens, pc.Dim = uint32(rows), uint32(g.H)
756			pc.InOff, pc.OutOff = qk.src, qk.dst
757			pc.WOff, pc.Aux0 = g.wCos, g.wSin
758			pc.Aux1, pc.Aux2 = uint32(g.planeRows), g.wOnes
759			pc.Span, pc.Eps, pc.Scale = uint32(tiles), eps, math.Float32bits(qk.scale)
760			gr.add(g.pipes["qkpack"], qk.kind, uint32((tiles+7)/8), uint32(g.heads), pc, 0)
761		}
762		pc := gr.base
763		pc.Tokens, pc.Dim = uint32(rows), uint32(g.H)
764		pc.InOff, pc.OutOff = aV, g.hV
765		pc.Aux0, pc.Aux1, pc.Aux2 = 1, uint32(g.planeRows), uint32(tiles)
766		pc.Scale = math.Float32bits(1)
767		gr.add(g.pipes["pack"], "pack v", uint32((tiles+7)/8), uint32(g.heads), pc, 0)
768	
769		gr.attention(seqs)
770		if err := gr.gemm(gemmBig, w.bank, "gemm o", g.hCtx, aAttn, w.off[projO], rows, g.H, g.kH, g.ldaH); err != nil {
771			return err
772		}
773		gate("gate attn", aAttn, w.s1)
774		norm("ffn in", w.norm2)
775		if err := gr.gemm(gemmBig, w.bank, "gemm gate", g.hA, aGate, w.off[projGate], rows, g.ffn, g.kH, g.ldaH); err != nil {
776			return err
777		}
778		if err := gr.gemm(gemmBig, w.bank, "gemm up", g.hA, aUp, w.off[projUp], rows, g.ffn, g.kH, g.ldaH); err != nil {
779			return err
780		}
781		pcG := gr.base
782		pcG.Tokens, pcG.Dim, pcG.LDA = uint32(rows), uint32(g.ffn), uint32(g.ldaF)
783		pcG.InOff, pcG.KOff, pcG.OutOff = aGate, aUp, g.hFFN
784		pcG.Scale = math.Float32bits(1)
785		gr.add(g.pipes["swiglu"], "swiglu", uint32(rows), 1, pcG, 0)
786		if err := gr.gemm(gemmBig, w.bank, "gemm down", g.hFFN, aFF, w.off[projDown], rows, g.H, g.kF, g.ldaF); err != nil {
787			return err
788		}
789		gate("gate ffn", aFF, w.s2)
790		return nil
791	}
