793	// attention records the packed planes' attention into hCtx, a sequence at
794	// a time, each over its own keys.
795	func (gr *graph) attention(seqs int) {
796		g := gr.g
797		planeTile := uint32(g.headDim * tile) // halves a 16-row tile of one head
798		rowsPer := g.attn.QT * tile
799		for s := 0; s < seqs; s++ {
800			t0 := uint32(s*g.stride/tile) * planeTile
801			pc := gr.base
802			pc.Tokens = uint32(g.seqLen)
803			pc.InOff, pc.KOff, pc.VOff = g.hQ+t0, g.hK+t0, g.hV+t0
804			pc.OutOff, pc.LDA = g.hCtx+uint32(s*g.stride*g.ldaH), uint32(g.ldaH)
805			pc.Aux1 = uint32(g.planeRows)
806			gr.add(g.attnPipes[g.attn], "attention", uint32((g.seqLen+rowsPer-1)/rowsPer), uint32(g.heads), pc,
807				4*float64(g.seqLen)*float64(g.seqLen)*float64(g.headDim)*float64(g.heads))
808		}
809	}
