811	// input writes a batch's proj_in operand: each tile-clip's latents
812	// (post_quant_conv applied, [24, 7, th, tw]) as rows in (t, h, w) order with
813	// the bias column set, then its registers' one-hot rows; the zero token and
814	// the stride's pad rows are all zero.
815	func (g *GPU) input(clips []*Tensor) {
816		c := g.cfg
817		L := c.LatentChannels
818		buf := make([]uint16, len(clips)*g.stride*g.ldaIn)
819		one := safetensors.F32ToF16(1)
820		parallelFor(len(clips), func(s int) {
821			z := clips[s]
822			hw := z.H * z.W
823			base := s * g.stride * g.ldaIn
824			for t := 0; t < z.T; t++ {
825				for p := 0; p < hw; p++ {
826					row := buf[base+(t*hw+p)*g.ldaIn:]
827					for ch := 0; ch < L; ch++ {
828						row[ch] = safetensors.F32ToF16(z.Data[(ch*z.T+t)*hw+p])
829					}
830					row[L] = one
831				}
832			}
833			for r := 0; r < c.Registers; r++ {
834				buf[base+(z.T*hw+r)*g.ldaIn+L+1+r] = one
835			}
836		})
837		g.hbuf.WriteUint16At(int(g.hIn), buf)
838	}
