840	// run records and submits the whole decoder over the batch's sequences: the
841	// input GEMM straight into the residual, the blocks, and the tail into
842	// aOut. last < 0 runs every block, and tail false stops after them.
843	func (g *GPU) run(seqs, first, last int, input, tail bool) (time.Duration, error) {
844		if err := g.chooseAttention(); err != nil {
845			return 0, err
846		}
847		gr := g.newGraph()
848		rows := seqs * g.stride
849		if input {
850			if err := gr.gemm(gemmBig, g.projIn.bank, "gemm proj_in", g.hIn, g.aX, g.projIn.off, rows, g.H, g.kIn, g.ldaIn); err != nil {
851				return 0, err
852			}
853		}
854		if last < 0 {
855			last = len(g.blocks)
856		}
857		for b := first; b < last; b++ {
858			if err := gr.blockPass(g.blocks[b], seqs); err != nil {
859				return 0, err
860			}
861		}
862		if tail {
863			pc := gr.base
864			pc.Tokens, pc.Dim, pc.LDA = uint32(rows), uint32(g.H), uint32(g.ldaH)
865			pc.InOff, pc.OutOff = g.aX, g.hA
866			pc.Aux0, pc.Eps = g.aNormOut, math.Float32bits(float32(g.cfg.NormEps))
867			gr.add(g.pipes["finalnorm"], "norm out", uint32(rows), 1, pc, 0)
868			if err := gr.gemm(gemmBig, g.projOut.bank, "gemm proj_out", g.hA, g.aOut, g.projOut.off, rows, g.projOut.n, g.H, g.ldaH); err != nil {
869				return 0, err
870			}
871		}
872		return gr.submit()
873	}
