					for dy := 0; dy < ps; dy++ {
						dst := v.idx(ch, f*pt+dt, y*ps+dy, x*ps)
						for dx := 0; dx < ps; dx++ {
							v.Data[dst+dx] = row[i] + g.outBias[i]
							i++
						}
					}
				}
			}
		}
		out[s] = v
	})
